package com.nigson.commerce.fulfillment;
import java.net.*;
import java.time.*;
import java.util.*;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import com.nigson.shared.events.EventCodec;
import static org.assertj.core.api.Assertions.*;
class HttpCarrierCancellationTest {
 HttpServer server;String base;CarrierCancellationValues.Command input;String response;int status=202;String contentType="application/json";Throwable violation;
 @BeforeEach void setup()throws Exception{input=new CarrierCancellationValues.Command(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"123456789012","MOCK",Instant.now());server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);base="http://127.0.0.1:"+server.getAddress().getPort();response=EventCodec.JSON.writeValueAsString(Map.of("cancellationId",input.cancellationId(),"shipmentId",input.shipmentId(),"state","QUEUED"));server.createContext("/",x->{try{assertThat(x.getRequestURI().getPath()).isEqualTo("/internal/v1/carrier/cancellations");assertThat(x.getRequestMethod()).isEqualTo("POST");assertThat(x.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer synthetic-workload");assertThat(x.getRequestHeaders().getFirst("Idempotency-Key")).isEqualTo(input.cancellationId().toString());assertThat(x.getRequestHeaders().getFirst("Cookie")).isNull();assertThat(x.getRequestHeaders().getFirst("X-Nigson-Actor")).isNull();assertThat(EventCodec.JSON.readTree(x.getRequestBody().readAllBytes())).isEqualTo(EventCodec.JSON.valueToTree(input));byte[] bytes=response.getBytes(java.nio.charset.StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type",contentType);x.sendResponseHeaders(status,bytes.length);x.getResponseBody().write(bytes);}catch(Throwable failure){violation=failure;}finally{x.close();}});server.start();}
 @AfterEach void cleanup(){server.stop(0);assertThat(violation).isNull();}
 CarrierCancellationValues.Acknowledgement exchange(){return new HttpCarrierCancellation("test",base,route->{assertThat(route.scope()).isEqualTo("carrier.cancel");return "synthetic-workload";}).exchange(input,UUID.randomUUID());}
 @Test void queuedAcknowledgementAllowsOmittedAndExplicitNullReceipt(){assertThat(exchange().receipt()).isNull();response=response.substring(0,response.length()-1)+",\"receipt\":null}";assertThat(exchange().state()).isEqualTo("QUEUED");}
 @Test void savedReceiptIsBoundToOriginalSourceFacts(){var receipt=new CarrierCancellationValues.Receipt(UUID.randomUUID(),input.cancellationId(),input.shipmentId(),input.bookingRequestId(),input.reference(),input.mode(),"CANCELLED",Instant.now(),"NONE");response=EventCodec.JSON.writeValueAsString(new CarrierCancellationValues.Acknowledgement(input.cancellationId(),input.shipmentId(),"CANCELLED",receipt));assertThat(exchange().receipt()).isEqualTo(receipt);response=response.replace(input.bookingRequestId().toString(),UUID.randomUUID().toString());assertThatThrownBy(this::exchange).hasMessage("PROVIDER_OUTCOME_UNKNOWN");}
 @Test void duplicateTrailingUnknownAndOversizedRepliesStayUnknown(){String valid=response;for(String malformed:List.of(valid+" {}",valid.replace("\"state\":\"QUEUED\"","\"state\":\"QUEUED\",\"state\":\"CANCELLED\""),valid.substring(0,valid.length()-1)+",\"account\":\"protected\"}"," ".repeat(65537))){response=malformed;assertThatThrownBy(this::exchange).hasMessage("PROVIDER_OUTCOME_UNKNOWN");}}
 @Test void wrongIdentityRedirectAndMalformedMimeCannotProduceSuccess(){response=response.replace(input.shipmentId().toString(),UUID.randomUUID().toString());assertThatThrownBy(this::exchange).hasMessage("PROVIDER_OUTCOME_UNKNOWN");status=302;assertThatThrownBy(this::exchange).hasMessage("PROVIDER_OUTCOME_UNKNOWN");status=202;contentType="text/html";assertThatThrownBy(this::exchange).hasMessage("PROVIDER_OUTCOME_UNKNOWN");}
 @Test void productionCannotFallBackToLocalOrMockTargets(){assertThatThrownBy(()->new HttpCarrierCancellation("prod",base,r->"synthetic")).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new HttpCarrierCancellation("test","https://example.invalid",r->"synthetic")).isInstanceOf(IllegalArgumentException.class);}
}
